      "topic": {
        "text": "Java bytecode",
        "refs": ["Q0003"]
      },
      "explanation_text": {
        "text": "Java bytecode is platform independent and can run on Windows, macOS, Linux, or any operating system that has a Java Runtime Environment (JRE).",
        "refs": ["Q0003"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Java Virtual Machine (JVM)",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "The JVM takes Java bytecode and translates it to native code for the underlying operating system, enabling the same bytecode to run on different platforms.",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Case sensitivity of file names",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "On macOS and Linux, file names are case‑sensitive, so the class name must be spelled with a capital ‘M’ (Main.java).",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "The compiled class file (bytecode) is stored in an output folder separate from the source folder.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The Java Runtime Environment includes the JVM, which executes Java bytecode.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "C# and Python also have architectures that make them platform independent.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
