  "procedures": [
    {
      "procedure_name": {
        "text": "Compile a Java source file",
        "refs": ["Q0001"]
      },
      "steps": [
        {
          "text": "Open a terminal (or command prompt) in the folder containing the source file.",
          "refs": ["Q0000"]
        },
        {
          "text": "Run the Java compiler: `javac Main.java` (use the exact case of the filename on macOS/Linux).",
          "refs": ["Q0001"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "Compiles the Java source file into a .class bytecode file.",
        "refs": ["Q0001"]
      }
    },
    {
      "procedure_name": {
        "text": "Run a compiled Java program",
        "refs": ["Q0005"]
      },
      "steps": [
        {
          "text": "In the terminal, execute the JVM with the class name: `java Main`.",
          "refs": ["Q0005"]
        }
